ST.xhtml:p:
RTrigger1(CLK := g_bMiddleAvoidAxis1GearInM OR bGearIn);
RTrigger2(CLK := g_bMiddleAvoidAxis1GearOutM OR bGearOut);
(*主卡进给轴*)
IF RTrigger1.Q THEN
  IF g_bIsConfigMiddleAvoidAxis1 THEN
    IF AntiRejection4.NCTOPLC.AxisState <> 8 THEN
      nGearState := 1;
      g_bMiddleAvoidAxis1GearDone := FALSE;
    ELSIF AntiRejection4.NCTOPLC.AxisState = 8 THEN
      M.ENABLE[318] := 0;
      g_bMiddleAvoidAxis1GearDone := TRUE;
    END_IF;
    bGearIn := FALSE;
    g_bMiddleAvoidAxis1GearInM := FALSE;
  ELSE 
    M.ENABLE[318] := 0; 
    bGearIn := FALSE;
    g_bMiddleAvoidAxis1GearInM := FALSE;  
  END_IF;
END_IF;

IF RTrigger2.Q THEN
  IF g_bIsConfigMiddleAvoidAxis1 THEN
    IF AntiRejection4.NCTOPLC.AxisState = 8 THEN
      nGearState := 2;
      g_bMiddleAvoidAxis1GearDone := FALSE;
    ELSIF AntiRejection4.NCTOPLC.AxisState <> 8 THEN
      M.ENABLE[318] := 0;
      g_bMiddleAvoidAxis1GearDone := TRUE;
    END_IF;
    g_bMiddleAvoidAxis1GearOutM := FALSE;
    bGearOut := FALSE;
  ELSE
    M.ENABLE[318] := 0; 
    bGearOut := FALSE;
    g_bMiddleAvoidAxis1GearOutM := FALSE;  
  END_IF;    
END_IF;

CASE nGearState OF
  0:
    nGearState := 0;
  1:
    g_MiddleAvoidAxis1GearIn.Execute := TRUE;
     g_MiddleAvoidAxis1GearIn.RatioNumerator := 1.0;
    g_MiddleAvoidAxis1GearIn.RatioDenominator := 1; 
    IF g_MiddleAvoidAxis1GearIn.InGear THEN
      g_bMiddleAvoidAxis1GearDone := TRUE;
      nGearState := 0;
      M.ENABLE[318] := 0;
    END_IF;
    IF g_MiddleAvoidAxis1GearIn.Error OR g_MiddleAvoidAxis1GearIn.CommandAborted THEN
      g_MiddleAvoidAxis1GearIn.Execute := FALSE;
      nGearState := 0;
    END_IF;
  2:
    g_MiddleAvoidAxis1GearOut.Execute := TRUE;
    g_MiddleAvoidAxis1GearIn.Execute := FALSE;
    IF g_MiddleAvoidAxis1GearOut.Done THEN
      g_MiddleAvoidAxis1GearOut.Execute := FALSE;
      IF AntiRejection4.NCTOPLC.AxisState = 2 OR AntiRejection4.NCTOPLC.AxisState = 1 THEN
        nGearState := 0;
      ELSE
        nGearState := 3;
      END_IF;
       M.ENABLE[318] := 0;
       g_bMiddleAvoidAxis1GearDone := TRUE;
    END_IF;
    IF g_MiddleAvoidAxis1GearOut.Error THEN
      g_MiddleAvoidAxis1GearOut.Execute := FALSE;
      nGearState := 0;
    END_IF;
  3:
    g_AntiRejection4Stop.Execute := TRUE;
    IF g_AntiRejection4Stop.Done THEN
      g_AntiRejection4Stop.Execute := FALSE;
      nGearState := 0;
    END_IF;
    IF g_AntiRejection4Stop.Commandaborted OR g_AntiRejection4Stop.Error THEN
      g_AntiRejection4Stop.Execute := FALSE;
      nGearState := 0;
    END_IF;
END_CASE;



RTrigger3(CLK := g_bMiddleAvoidAxis2GearInM OR bGearIn1);
RTrigger4(CLK := g_bMiddleAvoidAxis2GearOutM OR bGearOut1);

IF RTrigger3.Q THEN
  IF g_bIsConfigMiddleAvoidAxis2 THEN
    IF AntiRejection5.NCTOPLC.AxisState <> 8 THEN
      nGearState1 := 1;
      g_bMiddleAvoidAxis2GearDone := FALSE;
    ELSIF AntiRejection5.NCTOPLC.AxisState = 8 THEN
      M.ENABLE[318] := 0;
      g_bMiddleAvoidAxis2GearDone := TRUE;
    END_IF;
    bGearIn1 := FALSE;
    g_bMiddleAvoidAxis2GearInM := FALSE;
  ELSE
    M.ENABLE[318] := 0;
    bGearIn1 := FALSE;
    g_bMiddleAvoidAxis2GearInM := FALSE;  
  END_IF;  
END_IF;

IF RTrigger4.Q THEN
  IF g_bIsConfigMiddleAvoidAxis2 THEN
    IF AntiRejection5.NCTOPLC.AxisState = 8 THEN
      nGearState1 := 2;
      g_bMiddleAvoidAxis2GearDone := FALSE;
    ELSIF AntiRejection5.NCTOPLC.AxisState <> 8 THEN
      M.ENABLE[318] := 0;
      g_bMiddleAvoidAxis2GearDone := TRUE;
    END_IF;
    g_bMiddleAvoidAxis2GearOutM := FALSE;
    bGearOut1 := FALSE;
  ELSE
    M.ENABLE[318] := 0;
    bGearIn1 := FALSE;
    g_bMiddleAvoidAxis2GearInM := FALSE;  
  END_IF;  
END_IF;

CASE nGearState1 OF
  0:
    nGearState1 := 0;
  1:
    g_MiddleAvoidAxis2GearIn.Execute := TRUE;
    g_MiddleAvoidAxis2GearIn.RatioNumerator := 1.0;
    g_MiddleAvoidAxis2GearIn.RatioDenominator := 1;
    IF g_MiddleAvoidAxis2GearIn.InGear THEN
      g_bMiddleAvoidAxis2GearDone := TRUE;
      nGearState1 := 0;
       M.ENABLE[318] := 0;

    END_IF;
    IF g_MiddleAvoidAxis2GearIn.Error OR g_MiddleAvoidAxis2GearIn.CommandAborted THEN
      g_MiddleAvoidAxis2GearIn.Execute := FALSE;
      nGearState1 := 0;
    END_IF;
  2:
    g_MiddleAvoidAxis2GearOut.Execute := TRUE;
    g_MiddleAvoidAxis2GearIn.Execute := FALSE;
    IF g_MiddleAvoidAxis2GearOut.Done THEN
      g_MiddleAvoidAxis2GearOut.Execute := FALSE;
      IF AntiRejection5.NCTOPLC.AxisState = 2 OR AntiRejection5.NCTOPLC.AxisState = 1 THEN
        nGearState1 := 0;
      ELSE
        nGearState1 := 3;
      END_IF;
       M.ENABLE[318] := 0;
       g_bMiddleAvoidAxis2GearDone := TRUE;
    END_IF;
    IF g_MiddleAvoidAxis2GearOut.Error THEN
      g_MiddleAvoidAxis2GearOut.Execute := FALSE;
      nGearState1 := 0;
    END_IF;
  3:
    g_AntiRejection5Stop.Execute := TRUE;
    IF g_AntiRejection5Stop.Done THEN
      g_AntiRejection5Stop.Execute := FALSE;
      nGearState1 := 0;
    END_IF;
    IF g_AntiRejection5Stop.Commandaborted OR g_AntiRejection5Stop.Error THEN
      g_AntiRejection5Stop.Execute := FALSE;
      nGearState1 := 0;
    END_IF;
END_CASE;


IF Axis_Y0.NCTOPLC.ERRORCODE <> 0 AND g_bPlcResetBuffer THEN
  g_Y0Reset.EXECUTE := TRUE;
ELSE
  g_Y0Reset.EXECUTE := FALSE;
END_IF;
